def ncdf(v):
    return st.norm.cdf(v)

@test
def test_nan_omit():
    r = st.ttest_ind(xn, yn, nan_policy='omit')
    r2 = st.ttest_1samp(xn, 3.0, nan_policy='omit')
    r3 = st.ttest_rel(xn, yn, nan_policy='omit')
    assert close([r.statistic, r.pvalue, r.df, r2.statistic, r2.pvalue, r3.statistic, r3.pvalue], tt_omit)
    a = st.mannwhitneyu(xn, yn, nan_policy='omit')
    b = st.kendalltau(xn, yn, nan_policy='omit')
    c = st.ks_2samp(xn, yn, nan_policy='omit')
    d = st.ks_1samp(xn, ncdf, nan_policy='omit')
    assert close([a.statistic, a.pvalue, b.statistic, b.pvalue, c.statistic, c.pvalue, d.statistic, d.pvalue], np_omit)
    assert close(st.zscore(xn, nan_policy='omit'), zs_omit)
    assert close(st.rankdata(xn, nan_policy='omit'), rk_omit)
    assert close(st.rankdata(xn), rk_prop)

@test
def test_misc_funcs():
    assert close(st.gzscore(x), gz)
    r = st.sigmaclip(np.concatenate([x, np.array([40.0, -30.0])]), 2.0, 2.0)
    assert close(list(r.clipped) + [r.lower, r.upper], sc)
    ot = st.obrientransform(x, y)
    assert close(list(ot[0]) + list(ot[1]), ob)
    ds_ = st.directional_stats(np.array([[3., 4], [6, -8], [1, 2]]))
    assert close(list(ds_.mean_direction) + [ds_.mean_resultant_length], ds)
    assert close([st.expectile(x), st.expectile(x, 0.2), st.expectile(x, 0.8, weights=y)], ex)
    s1 = st.siegelslopes(y, x, method='separate')
    assert close([s1.slope, s1.intercept], sl)

@test
def test_lmoment_xi_quantile():
    assert close(st.lmoment(x), lm)
    assert close(st.lmoment(x, order=[1, 3, 5]), lm2)
    assert close(st.lmoment(X2, axis=1, standardize=False), lm3)
    r = st.chatterjeexi(x, y)
    assert close([r.statistic, r.pvalue], xi)
    r = st.chatterjeexi(np.round(x), np.round(y))
    assert close([r.statistic, r.pvalue], xi2)
    r = st.chatterjeexi(x, y, y_continuous=True)
    assert close([r.statistic, r.pvalue], xi3)
    out = []
    for alt in ['two-sided', 'less', 'greater']:
        q = st.quantile_test(x, q=3.5, p=0.4, alternative=alt)
        ci = q.confidence_interval(0.9)
        out += [q.statistic, q.statistic_type, q.pvalue, ci.low, ci.high]
    assert close(out, qt)

test_nan_omit()
test_misc_funcs()
test_lmoment_xi_quantile()
